interface Payments {
  charge(cents: number): string;
}
class LegacyGateway {
  bill(decimalAmount: string) {
    return `cobrado:${decimalAmount}`;
  }
}
class PaymentAdapter implements Payments {
  constructor(private gateway: LegacyGateway) {}
  charge(cents: number) {
    if (!Number.isSafeInteger(cents) || cents < 0)
      throw new Error('Centavos inválidos');
    return this.gateway.bill((cents / 100).toFixed(2));
  }
}
export function demo() {
  const payments: Payments = new PaymentAdapter(new LegacyGateway());
  return payments.charge(1590);
}

interface Channel {
  deliver(text: string): string;
}
class Email implements Channel {
  deliver(text: string) {
    return `email:${text}`;
  }
}
class Journal implements Channel {
  deliver(text: string) {
    return `log:${text}`;
  }
}
class Notice {
  constructor(protected channel: Channel) {}
  send(text: string) {
    return this.channel.deliver(text);
  }
}
class UrgentNotice extends Notice {
  override send(text: string) {
    return this.channel.deliver(`URGENTE ${text}`);
  }
}
export function demo() {
  return [
    new Notice(new Email()).send('A'),
    new UrgentNotice(new Journal()).send('B'),
  ];
}

interface Work {
  minutes(): number;
}
class Task implements Work {
  constructor(private duration: number) {}
  minutes() {
    return this.duration;
  }
}
class WorkGroup implements Work {
  constructor(private children: Work[]) {}
  minutes(): number {
    return this.children.reduce((total, child) => total + child.minutes(), 0);
  }
}
export function demo() {
  const preparation = new WorkGroup([new Task(10), new Task(15)]);
  const plan = new WorkGroup([preparation, new Task(20)]);
  return plan.minutes();
}

interface Reader {
  read(): string;
}
class Cached implements Reader {
  private value: string | undefined;
  constructor(private inner: Reader) {}
  read() {
    return (this.value ??= this.inner.read());
  }
}
class Metered implements Reader {
  calls = 0;
  constructor(private inner: Reader) {}
  read() {
    this.calls++;
    return this.inner.read();
  }
}
export function demo() {
  const source = { read: () => 'conteudo' };
  const inside = new Metered(source);
  const cached = new Cached(inside);
  cached.read();
  cached.read();
  const outside = new Metered(new Cached(source));
  outside.read();
  outside.read();
  return { inside: inside.calls, outside: outside.calls };
}

class MaterialStore {
  save(text: string) {
    return { id: 'material-1', text };
  }
}
class SearchIndex {
  indexed: string[] = [];
  add(id: string) {
    this.indexed.push(id);
  }
}
class Publisher {
  constructor(
    private store: MaterialStore,
    private index: SearchIndex,
  ) {}
  publish(text: string) {
    if (!text.trim()) throw new Error('Material vazio');
    const saved = this.store.save(text.trim());
    this.index.add(saved.id);
    return saved.id;
  }
}
export function demo() {
  const index = new SearchIndex();
  const publisher = new Publisher(new MaterialStore(), index);
  return { id: publisher.publish(' Conceito '), indexed: index.indexed };
}

type Style = Readonly<{ sector: string; color: string }>;
class Styles {
  private values = new Map<string, Style>();
  get(sector: string, color: string) {
    const key = JSON.stringify([sector, color]);
    if (!this.values.has(key))
      this.values.set(key, Object.freeze({ sector, color }));
    return this.values.get(key)!;
  }
}
export function demo() {
  const styles = new Styles();
  const a = { row: 1, seat: 1, style: styles.get('A', 'azul') };
  const b = { row: 1, seat: 2, style: styles.get('A', 'azul') };
  return { shared: a.style === b.style, positions: [a.seat, b.seat] };
}

interface Document {
  read(allowed: boolean): string;
}
class ProtectedPreview implements Document {
  private real: { read(): string } | undefined;
  constructor(private create: () => { read(): string }) {}
  read(allowed: boolean) {
    if (!allowed) throw new Error('Acesso negado');
    this.real ??= this.create();
    return this.real.read();
  }
}
export function demo() {
  let loads = 0;
  const preview = new ProtectedPreview(() => {
    loads++;
    return { read: () => 'texto' };
  });
  try {
    preview.read(false);
  } catch {
    /* Rejeição esperada. */
  }
  const deniedLoads = loads;
  preview.read(true);
  preview.read(true);
  return { deniedLoads, loads };
}
